/**
 * A plugin's name in each form the engine may spell its tools from: composed
 * and decomposed, one entry where the two are the same.
 *
 * The engine takes a listed id for a plugin by the composed form of both, and
 * spells the plugin's tools from its manifest's name as written.
 *
 * @param name a plugin's name, as policy lists it
 * @returns the name composed, and decomposed where that differs
 */
export const formsOf = (name: string): string[] => {
  const composed = name.normalize('NFC')
  const decomposed = name.normalize('NFD')

  return composed === decomposed ? [composed] : [composed, decomposed]
}

/**
 * The name half of a plugin id: everything before its LAST at-sign, as the
 * engine parts ids, so a scoped id (`@scope/name@npm`) keeps its scope.
 *
 * @param id a plugin id as policy lists it (`<name>@<marketplace>`)
 * @returns the name; the whole id where no at-sign follows a name
 */
export function nameOfId(id: string): string {
  const at = id.lastIndexOf('@')

  return at > 0 ? id.slice(0, at) : id
}

import type { Settings } from 'claude-code'

/**
 * The MCP servers managed policy names, as their tools are prefixed
 * (`mcp__<name>__`): allowlist entries with a serverName, and its own.
 *
 * Its own are the servers it delivers (managedMcpServers keys), which need
 * no allowedMcpServers entry.
 *
 * @param policy the managed settings, as `$.settings.read` answers them
 * @returns one name per named or delivered server; none without either
 */
export function orgServerNames(policy: Settings): string[] {
  const allowlist = policy.allowedMcpServers
  const delivered = policy.managedMcpServers
  const isMap = typeof delivered === 'object' && !Array.isArray(delivered)

  return [
    ...(Array.isArray(allowlist) ? allowlist : []).flatMap((entry: unknown) => {
      const isEntry =
        typeof entry === 'object' && entry !== null && 'serverName' in entry

      const name = isEntry ? entry.serverName : undefined
      const isNamed = typeof name === 'string' && name !== ''

      return isNamed ? [name] : []
    }),
    ...Object.keys(isMap ? (delivered ?? {}) : {}),
  ]
}

/**
 * How the engine spells a server's name inside its tools' names: every
 * character that is not a letter, digit, `_` or `-` becomes `_`.
 *
 * A claude.ai connector's runs of `_` are also joined and trimmed, so both
 * spellings are answered; one that comes out empty is left out.
 *
 * @param server the server's name as the policy spells it
 * @returns the spellings, without repeats
 */
export function spellingsOf(server: string): string[] {
  const spelt = server.replace(/[^a-zA-Z0-9_-]/g, '_')
  const joined = spelt.replace(/_+/g, '_').replace(/^_|_$/g, '')

  return [...new Set([spelt, joined])].filter(one => one !== '')
}

